#!/bin/bash\n\n# RMT Admin System Startup Script\necho \"🚀 Starting RMT Admin System...\"\necho \"================================\"\n\n# Check if .env.local exists\nif [ ! -f \".env.local\" ]; then\n    echo \"❌ .env.local file not found!\"\n    echo \"Please create .env.local with the following variables:\"\n    echo \"MONGODB_URI=your_mongodb_connection_string\"\n    echo \"BLOB_READ_WRITE_TOKEN=your_vercel_blob_token\"\n    exit 1\nfi\n\n# Check if node_modules exists\nif [ ! -d \"node_modules\" ]; then\n    echo \"📦 Installing dependencies...\"\n    npm install\nfi\n\n# Test the system\necho \"🧪 Testing system...\"\nnode test-admin-system.js\n\nif [ $? -eq 0 ]; then\n    echo \"\"\n    echo \"✅ System test passed!\"\n    echo \"🌐 Starting development server...\"\n    echo \"\"\n    echo \"Admin Panel will be available at:\"\n    echo \"http://localhost:3000/admin\"\n    echo \"\"\n    echo \"Login credentials:\"\n    echo \"Username: admin\"\n    echo \"Password: rmt2024\"\n    echo \"\"\n    \n    # Start the development server\n    npm run dev\nelse\n    echo \"❌ System test failed. Please check the configuration.\"\n    exit 1\nfi